test-case.test:
let $lib := fn:update(
  json-doc('update/library.json'),
  fn { .//draft/.., .//amount, .//topic },
  fn($n) {
    let $key := string(jkey($n))
    return if ($key = 'amount') then round(jvalue($n) * 1.1, 2)
      else if ($key = 'topic') then { 'subject': jvalue($n) }
      else ()
  }
)
return { 'books': count($lib//title), 'total': sum($lib//amount ! jvalue()),
  'subjects': string-join($lib//subject ! string(), ' ') }

let $doc := fn:update(.,
  fn { .//text()[not(normalize-space())] })
return fn:update(
  $doc,
  fn { .//book[@draft] | .//price | .//shelf },
  fn($n) {
    if ($n/self::book) then ()
    else if ($n/self::price) then round($n * 1.1, 2)
    else <shelf count="{ count($n/book) }">{ $n/@*, $n/node() }</shelf>
  }
)

let $a := fn:update(parse-xml("<a b='1'/>")/a, fn { .//@b }, parse-xml("<x xmlns:p='u' p:c='2'/>")/x/@*)
let $c := $a/@*
return (namespace-uri($c), namespace-uri-for-prefix(prefix-from-QName(node-name($c)), $a))

let $a := fn:update(<a xmlns:p="u1" p:b="1"/>, fn { .//@*:b }, attribute { QName('u2', 'p:c') } { 2 })
let $c := $a/@*
return (namespace-uri($c), namespace-uri-for-prefix(prefix-from-QName(node-name($c)), $a))

fn:update(
  element-to-map(fn:update(.,
    fn { .//text()[not(normalize-space())] | .//book[@draft] })),
  fn { .//'@currency' }
)//'title' ! string()

let $doc := fn:update(.,
  fn { .//text()[not(normalize-space())] })
return fn:update(
  element-to-map($doc),
  fn { .//'@draft'/.., .//price/'#content', .//'@topic' },
  fn($n) {
    let $key := string(jkey($n))
    return if ($key = '@topic') then { 'topic': jvalue($n) }
      else if ($key = '#content') then round(jvalue($n) * 1.1, 2)
      else ()
  }
)
